SELECT
sss.id,
sss.title,
sss.cover,
sss.audit_status AS auditStatus,
sss.summary,
sss.create_time AS createTime,
u.avatar,
u.username
FROM scenic_spot_strategy sss
LEFT JOIN user u ON u.id = sss.user_id


        AND sss.title LIKE concat('%',#{title},'%')


        AND sss.scenic_spot_id = #{scenicSpotId}


        AND sss.user_id = #{userId}


        AND sss.audit_status = #{auditStatus}


        AND sss.create_time BETWEEN #{startTime} AND #{endTime}


        AND sss.id IN

            #{id}



ORDER BY sss.create_time DESC

    LIMIT #{current},#{size}

